VALUES
  ('ass_prem_f1_0001', 'Não quero', ARRAY['1761742057377x784709806988197900', '1761742075865x914738701678673900', '1761742085261x485672521572548600', '1761742108026x685329439456231400'], 'Adote um Aluno – Solução Recifense Contra a Evasão Escolar', 'pedrocasefilho2208@gmail.com', NULL, NULL, ARRAY['1761746284676x787676075823202300', '1761746300807x372678499226353660', '1761746324002x353823270557188100', '1761746343263x632670681212911600'], 'ass-prem-fase1-0001'),
  ('ass_prem_f1_0002', 'A OBI/NOOK atende ao público-alvo (startup) e apresenta proposta alinhada a educação inclusiva com potencial social. Pelo que vi, faltam comprovações formais (CNPJ em recife) e a categoria tração sugiro a mudança para ascenção.', ARRAY['1761742057377x784709806988197900', '1761742085261x485672521572548600', '1761742075865x914738701678673900', '1761742108026x685329439456231400'], 'OBI', 'evisson.lucena@recife.pe.gov.br', NULL, NULL, ARRAY['1761758727117x733163620295245800', '1761758948401x376893710579793900', '1761758959021x438902190006075400', '1761758992260x982788837743001600'], 'ass-prem-fase1-0002'),
  ('ass_prem_f1_0003', 'Faltando CCNPJ. e Sugestão de migrar de categoria.', ARRAY['1761742057377x784709806988197900', '1761742075865x914738701678673900', '1761742085261x485672521572548600', '1761742108026x685329439456231400'], 'Biosurfatech: Limpeza Sustentável com o Poder dos Microrganismos', 'evisson.lucena@recife.pe.gov.br', NULL, NULL, ARRAY['1761763417320x846795629951713300', '1761763476659x470620404213350400', '1761763517079x444992736263405600', '1761763541922x984063285160312800'], 'ass-prem-fase1-0003'),
