  ('val_import_00495', 'Solução excelente, une dispositivos complementares (smartphone, óculos e bengala inteligente).', '1750965024848x176365381922324480', NULL, NULL, NULL, NULL, 'fernandosouza@recife.pe.gov.br', 'val-import-00495'),
  ('val_import_00496', NULL, '1750965055572x808870400252969000', NULL, NULL, NULL, NULL, 'fernandosouza@recife.pe.gov.br', 'val-import-00496'),
  ('val_import_00497', 'Em relação aos demais concorrentes a solução de fato tem o melhor custo benefício, ainda une óculos com a bengala inteligente.', '1750965084733x626654352174481400', NULL, NULL, NULL, NULL, 'fernandosouza@recife.pe.gov.br', 'val-import-00497'),
  ('val_import_00498', 'Tecnologias contendo dispositivos e software leves e de fácil manutenção.', '1750965113035x319882309975408640', NULL, NULL, NULL, NULL, 'fernandosouza@recife.pe.gov.br', 'val-import-00498'),
  ('val_import_00499', 'Como a solução precisa de equipamentos complementares óculos e bengala inteligente, acredito que a escalabilidade rápida pode se tornar desafiadora na produção dos itens.', '1750965138894x984751957414510600', NULL, NULL, NULL, NULL, 'fernandosouza@recife.pe.gov.br', 'val-import-00499'),
  ('val_import_00500', 'Todos os itens foram bem preenchidos.', '1750965182829x394638459540865000', NULL, NULL, NULL, NULL, 'fernandosouza@recife.pe.gov.br', 'val-import-00500'),
